'use strict';
function dashboardNavigation(){return '<nav class="dashboard-links" aria-label="Workspaces"><a href="/#/">Shop</a>'+(KstoreCloud.isAdmin?'<a href="/admin">Admin dashboard</a>':'')+(state.seller?'<a href="/seller">Seller dashboard</a>':'<a href="/seller/onboarding">Become a seller</a>')+'<a href="/rider">Rider dashboard</a></nav>';}
function adminApplicants(items,kind){return items.length?items.map(a=>{const pending=kind==='seller'?a.verificationStatus==='pending'&&a.status==='active'&&a.submittedAt:a.status==='pending';return '<article class="panel section"><h3>'+esc(kind==='seller'?a.shopName:a.name)+'</h3><p>'+esc(kind==='seller'?a.ownerName:a.name)+' · '+esc(kind==='seller'?a.ownerEmail:a.email)+'</p><p>'+esc(a.phone||'')+'</p><span class="status">'+esc(kind==='seller'?a.verificationStatus:a.status)+'</span>'+(kind==='seller'&&!a.submittedAt?'<p>Application has not been submitted.</p>':'')+(pending?'<p><button class="primary" data-admin-approve="'+kind+'" data-id="'+esc(a.id)+'">Review approval</button></p>':'')+'</article>';}).join(''):'<div class="panel empty">No '+(kind==='seller'?'seller':'rider')+' records loaded.</div>';}
function adminOrderRows(items){return items.length?'<div class="dashboard-table"><table><thead><tr><th>Order</th><th>Status</th><th>Delivery</th><th>Total</th><th>Payment</th></tr></thead><tbody>'+items.map(o=>'<tr><td>'+esc(o.id)+'</td><td>'+esc(o.status)+'</td><td>'+esc(o.status==='Cancelled'?'Cancelled':o.deliveryAssignment?.status||'Unassigned')+(o.deliveryAssignment?.failureReason?'<br>'+esc(o.deliveryAssignment.failureReason):'')+'</td><td>'+money(o.total)+'</td><td>'+esc(o.paymentStatus)+'</td></tr>').join('')+'</tbody></table></div>':'<div class="panel empty">No matching orders in the loaded records.</div>';}
async function adminReload(){if(KstoreCloud.adminLoading)return;const user=KstoreCloud.auth?.uid;KstoreCloud.adminLoading=true;KstoreCloud.adminError=null;render();try{const data=await KstoreCloud.loadAdminData();if(KstoreCloud.auth?.uid===user)KstoreCloud.adminData=data;}catch(e){if(KstoreCloud.auth?.uid===user)KstoreCloud.adminError=e.message;}finally{if(KstoreCloud.auth?.uid===user){KstoreCloud.adminLoading=false;render();}}}
function adminPage(){
 if(!state.user)return login();
 if(!KstoreCloud.auth?.emailVerified)return '<section class="panel empty"><h1>Verify your administrator email</h1><button class="secondary" data-firebase-action="refresh-auth">Refresh verification</button></section>';
 if(!KstoreCloud.isAdmin)return '<section class="panel empty"><h1>Administrator access required</h1><p>This account cannot approve applications or view platform operations.</p><button class="secondary" data-dashboard-refresh>Refresh access</button><p><a href="/#/">Return to shop</a></p></section>';
 if(!KstoreCloud.adminData&&!KstoreCloud.adminLoading&&!KstoreCloud.adminError)queueMicrotask(adminReload);
 const tab=route().path.split('/')[2]||'overview',d=KstoreCloud.adminData||{stores:[],couriers:[],orders:[]},problems=d.orders.filter(o=>o.status!=='Cancelled'&&o.deliveryAssignment?.status==='Delivery failed'),cash=d.orders.filter(o=>o.paymentStatus==='Cash collected — awaiting settlement');
 const tabs=[['overview','Overview'],['sellers','Sellers'],['riders','Riders'],['orders','Orders'],['delivery','Delivery problems'],['cash','Cash review']];
 const body=tab==='sellers'?adminApplicants(d.stores,'seller'):tab==='riders'?adminApplicants(d.couriers,'rider'):tab==='orders'?adminOrderRows(d.orders):tab==='delivery'?adminOrderRows(problems):tab==='cash'?'<p>Recorded cash collection awaiting reconciliation. This dashboard does not settle funds.</p>'+adminOrderRows(cash):'<div class="dashboard-stats">'+[['Seller applications',d.stores.filter(s=>s.verificationStatus==='pending'&&s.submittedAt).length],['Rider applications',d.couriers.filter(c=>c.status==='pending').length],['Delivery problems',problems.length],['Awaiting settlement',cash.length]].map(([label,n])=>'<div class="panel"><h3>'+esc(label)+'</h3><strong>'+n+'</strong></div>').join('')+'</div><section class="section"><h2>Recent orders</h2>'+adminOrderRows(d.orders.slice(0,10))+'</section>';
 return '<div class="section-head"><div><span class="eyebrow">KSTORE OPERATIONS</span><h1>Admin dashboard</h1></div><button class="secondary" data-admin-reload '+(KstoreCloud.adminLoading?'disabled':'')+'>Refresh records</button></div><nav class="dashboard-links" aria-label="Admin sections">'+tabs.map(([path,label])=>'<a href="/admin'+(path==='overview'?'':'/'+path)+'" '+(tab===path?'aria-current="page"':'')+'>'+label+'</a>').join('')+'</nav><p class="muted small">Up to 50 records per section. Counts describe loaded records; orders show the 50 most recent.</p>'+(KstoreCloud.adminLoading?'<p role="status">Loading operations…</p>':'')+(KstoreCloud.adminError?'<p class="error" role="alert">'+esc(KstoreCloud.adminError)+'</p>':'')+body;
}
const dashboardsOriginalRender=render;render=function(){const path=route().path;if(KstoreCloud.enabled&&(!KstoreCloud.auth||(path.startsWith('/admin')&&!KstoreCloud.isAdmin))&&$('#modal').open)$('#modal').close();if(KstoreCloud.enabled&&path.startsWith('/admin')){const body=!KstoreCloud.ready||!KstoreCloud.catalogReady?KstoreFirebaseUI.loading():adminPage();$('#app').innerHTML=header()+'<main class="wrap">'+dashboardNavigation()+body+'</main>'+footer();document.title='Admin dashboard | Kstore';return;}dashboardsOriginalRender();if(KstoreCloud.enabled&&(path==='/rider'||(dashboardPath(path)&&path.startsWith('/seller')))){const main=$('main');if(main){main.insertAdjacentHTML('afterbegin',dashboardNavigation());if(path==='/rider')document.title='Rider dashboard | Kstore';}}};
document.addEventListener('click',event=>{const anchor=event.target.closest('a[href]');if(!anchor||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||event.button!==0)return;const href=anchor.getAttribute('href'),target=href.startsWith('#/')?href.slice(1):href;if(!dashboardPath(target.split('?')[0]))return;event.preventDefault();go(target);},true);
window.addEventListener('click',event=>{const refresh=event.target.closest('[data-dashboard-refresh]');if(refresh){event.preventDefault();return deliveryRun(refresh,async()=>{await KstoreCloud.refreshRoles();});}const reload=event.target.closest('[data-admin-reload]');if(reload){event.preventDefault();return adminReload();}const approve=event.target.closest('[data-admin-approve]');if(approve){event.preventDefault();const kind=approve.dataset.adminApprove,id=approve.dataset.id,a=KstoreCloud.adminData?.[kind==='seller'?'stores':'couriers'].find(x=>x.id===id);if(!a)return;modal('Approve '+(kind==='seller'?'seller':'rider')+'?','<p>'+esc(kind==='seller'?a.shopName:a.name)+' · '+esc(kind==='seller'?a.ownerEmail:a.email)+'</p><p>'+(kind==='seller'?'This allows the seller to publish listings.':'This allows the rider to receive assignments and recipient delivery details.')+'</p><button class="primary" data-admin-confirm="'+kind+'" data-id="'+esc(id)+'">Confirm approval</button>');}const confirm=event.target.closest('[data-admin-confirm]');if(confirm){event.preventDefault();deliveryRun(confirm,async()=>{await KstoreCloud.call('adminReviewApplication',{kind:confirm.dataset.adminConfirm,uid:confirm.dataset.id});$('#modal').close();await adminReload();toast('Application approved.');});}},true);
if(KstoreCloud.enabled&&KstoreCloud.ready&&KstoreCloud.catalogReady)render();
